// Some portions generated by Codex
package org.eclipse.rdf4j.sail.memory;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Set;

import org.eclipse.rdf4j.common.transaction.IsolationLevels;
import org.eclipse.rdf4j.model.Resource;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.query.UpdateExecutionException;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.inferencer.InferencerConnection;
import org.junit.jupiter.api.Test;

class MemoryInferredContextIdsReviewTest {

	@Test
	void creatingAnExistingInferredOnlyGraphMustFail() {
		var vf = SimpleValueFactory.getInstance();
		var graph = vf.createIRI("urn:existing-inferred-context-review");
		SailRepository repository = new SailRepository(new MemoryStore());
		try (var connection = repository.getConnection()) {
			connection.begin();
			((InferencerConnection) connection.getSailConnection()).addInferredStatement(
					vf.createIRI("urn:s"), vf.createIRI("urn:p"), vf.createIRI("urn:o"), graph);
			connection.commit();
			assertTrue(connection.hasStatement(null, null, null, true, graph));

			assertThrows(UpdateExecutionException.class,
					() -> connection.prepareUpdate("CREATE GRAPH <" + graph.stringValue() + ">").execute());
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void publicContextIdsStillIncludeAnInferredOnlyNamedGraph() {
		var vf = SimpleValueFactory.getInstance();
		var graph = vf.createIRI("urn:inferred-context-review");
		SailRepository repository = new SailRepository(new MemoryStore());
		try (var connection = repository.getConnection()) {
			connection.begin();
			((InferencerConnection) connection.getSailConnection()).addInferredStatement(
					vf.createIRI("urn:s"), vf.createIRI("urn:p"), vf.createIRI("urn:o"), graph);
			connection.commit();
			assertFalse(connection.hasStatement(null, null, null, false, graph));
			assertTrue(connection.hasStatement(null, null, null, true, graph));

			for (boolean includeInferred : new boolean[] { false, true }) {
				var query = connection.prepareTupleQuery(QueryLanguage.SPARQL, "SELECT ?g WHERE { GRAPH ?g {} }");
				query.setIncludeInferred(includeInferred);
				try (var result = query.evaluate()) {
					assertEquals(includeInferred, result.hasNext());
					if (includeInferred) {
						assertEquals(graph, result.next().getValue("g"));
						assertFalse(result.hasNext());
					}
				}
			}

			try (var contexts = connection.getContextIDs()) {
				assertTrue(contexts.hasNext(), "Public context enumeration must retain the inferred-only graph");
				assertEquals(graph, contexts.next());
				assertFalse(contexts.hasNext());
			}
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void publicContextIdsAreDistinctAndFollowBothTransactionBranches() {
		var vf = SimpleValueFactory.getInstance();
		var explicit = vf.createIRI("urn:explicit");
		var inferred = vf.createBNode("inferred");
		var mixed = vf.createIRI("urn:mixed");
		var subject = vf.createIRI("urn:s");
		var predicate = vf.createIRI("urn:p");
		var object = vf.createIRI("urn:o");
		var repository = new SailRepository(new MemoryStore());
		try (var connection = repository.getConnection()) {
			connection.begin();
			connection.add(subject, predicate, object, explicit, mixed);
			connection.add(subject, predicate, object);
			var inferencer = (InferencerConnection) connection.getSailConnection();
			inferencer.addInferredStatement(object, predicate, subject, inferred, mixed);
			connection.commit();

			assertContexts(connection, explicit, inferred, mixed);
			connection.begin(IsolationLevels.SNAPSHOT);
			connection.clear(explicit, mixed);
			assertContexts(connection, inferred, mixed);
			inferencer.removeInferredStatement(object, predicate, subject, inferred);
			assertContexts(connection, mixed);
			connection.rollback();
			assertContexts(connection, explicit, inferred, mixed);
		} finally {
			repository.shutDown();
		}
	}

	private static void assertContexts(RepositoryConnection connection, Resource... expected) {
		try (var result = connection.getContextIDs()) {
			var ids = result.stream().toList();
			assertEquals(expected.length, ids.size());
			assertEquals(Set.of(expected), Set.copyOf(ids));
		}
	}
}
